head.script:
scwin.trigger1_onclick = function(e) {
    $p.executeSerial(["submission1", "submission2"]);
};
scwin.__isShowLogNormal = function() {
    var err = WebSquare.logger.getErrorLog();
    return !err;
}
scwin.unitTest = function() {
    //Unit
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    // Test step 1. 샘플파일을 실행 후 executeSerial 버튼을 클릭 후 ctrl+마우스우클릭 > 로그보기를 실행한다.
    //1. After executing the sample file, click the executeSerial button, and then right-click on ctrl + right-click> View log.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "100");
    // verify step 1. 로그에 오류가 없이 정상적으로 보여진다.(이전에는 Cannot read property "useModal" of null로그오류가 보여짐)
    //1. The log is displayed normally without errors.(Previously Can not read property "useModal" of null log error is shown) 
    WebSquare.wUnit.addCommand("assert", "scwin.__isShowLogNormal()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run test and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    //Function unitTest
    //Created By: Sang.do
    //Created By: 12-Mar-2018
    //end unitTest
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
